const seniorTopics={"daily": ["ga-adrc", "ga-cil-a2i", "ga-cil-bain", "ga-cil-dc", "ga-cil-dlink", "ga-cil-drc", "ga-cil-life", "ga-cil-mc", "ga-cil-nwga", "ga-cil-walton"], "accessibility": ["ga-adrc", "ga-cil-a2i", "ga-cil-bain", "ga-cil-dc", "ga-cil-dlink", "ga-cil-drc", "ga-cil-life", "ga-cil-mc", "ga-cil-nwga", "ga-cil-walton"], "vision": ["ga-adrc"], "hearing": ["ga-adrc"], "memory": ["alz-dementia-support", "ga-adrc"], "costs": ["ga-ship", "ga-adrc", "ga-legal-senior"], "rights": ["ga-ombudsman", "ga-legal-senior", "ga-legal-glsp", "ga-legal-alas"]};
const ohioLiving=DATA.filter(x=>x.resource_role==='independent_living').map(x=>x.program_id),ohioCaregivers=DATA.filter(x=>x.resource_role==='caregiver_support').map(x=>x.program_id);
const ohioCenters=DATA.filter(x=>x.resource_role==='senior_center').map(x=>x.program_id);
const ohioHome=DATA.filter(x=>x.resource_role==='home_support').map(x=>x.program_id);
seniorTopics.daily.push(...ohioCenters);routes.local.push(...ohioCenters);
